489:     while (nodes.length < frame.nodes.length) {
490:       const group = new THREE.Group();
491:       cylinder(group, 'supply mound', 1.4, 1.9, .45, [0, .18, 0], mat('#514936'), 7);
492:       for (let i = 0; i < 6; i++) {
493:         const crystal = new THREE.Mesh(new THREE.OctahedronGeometry(.65 + (i % 3) * .15, 0), mat(i % 2 ? '#c29c4d' : '#f0d477', .35, .3));
