410:   function render(frame) {
411:     currentZoom = frame.camera.z;
412:     resize();
413:     const centerX = (frame.camera.x - .5) * WORLD * aspect;
414:     const centerZ = (frame.camera.y - .5) * WORLD;
415:     camera.position.set(centerX, 190, centerZ + 92);
416:     camera.lookAt(centerX, 0, centerZ);
417:     camera.rotation.z = 0;
418:     camera.left = -HALF_VIEW * aspect / currentZoom; camera.right = HALF_VIEW * aspect / currentZoom;
419:     camera.top = HALF_VIEW / currentZoom; camera.bottom = -HALF_VIEW / currentZoom; camera.updateProjectionMatrix();
420: 
421:     const live = new Set();
422:     updateFog(frame);
423:     for (const entity of [...frame.buildings, ...frame.units, ...frame.enemies]) {
424:       live.add(entity.id);
425:       let obj = entities.get(entity.id);
426:       if (!obj || obj.userData.kind !== entity.kind || obj.userData.faction !== frame.faction) {
427:         if (obj) { entityRoot.remove(obj); disposeTree(obj); }
428:         obj = buildEntity(entity, frame.faction); entities.set(entity.id, obj); entityRoot.add(obj);
429:       }
430:       const scale = entity.size ? Math.max(.35, entity.size / 70) : Math.max(.85, entity.radius / 7);
431:       position(obj, entity.x, entity.y);
432:       obj.scale.setScalar(scale);
433:       const moving = entity.move && Math.hypot((entity.move.x - entity.x) * aspect, entity.move.y - entity.y) > .003;
434:       const moveAngle = moving ? Math.atan2(-(entity.move.x - entity.x) * aspect, -(entity.move.y - entity.y)) : null;
435:       const aimAngle = entity.target ? Math.atan2(-(entity.target.x - entity.x) * aspect, -(entity.target.y - entity.y)) : null;
436:       const turret = obj.userData.model.getObjectByName('turret');
437:       // Track actual displacement so AI-driven units and vehicles face their travel direction too.
438:       const previous = obj.userData.lastPosition;
439:       if (previous) {
440:         const dx = (entity.x - previous.x) * aspect, dy = entity.y - previous.y;
441:         if (dx * dx + dy * dy > 1e-8) obj.userData.heading = Math.atan2(-dx, -dy);
442:       }
443:       obj.userData.lastPosition = { x: entity.x, y: entity.y };
444:       // Models are built facing local -Z. Movement takes precedence; stationary combat units face targets.
445:       obj.rotation.y = entity.size ? 0 : (obj.userData.heading ?? moveAngle ?? (aimAngle !== null && !turret ? aimAngle : 0));
446:       const soldiers = obj.userData.model.userData.soldiers;
447:       if (soldiers) {
448:         const stride = moving ? Math.min(1, .45 + (entity.speed || 20) / 55) : 0;
449:         for (const gait of soldiers) {
450:           const swing = Math.sin(frame.time * 10 + gait.phase) * .52 * stride;
451:           for (const leg of gait.legs) leg.mesh.rotation.x = leg.base + swing;
452:           for (const arm of gait.arms) arm.mesh.rotation.x = arm.base - swing * .42;
453:           gait.soldier.position.y = gait.baseY + Math.abs(Math.sin(frame.time * 10 + gait.phase)) * .055 * stride;
454:         }
455:       }
456:       const fogIndex = Math.max(0, Math.min(127, Math.floor(entity.y * 128))) * 128 + Math.max(0, Math.min(127, Math.floor(entity.x * 128)));
457:       obj.visible = entity.hp > 0 && (entity.team === 'blue' || visibleCells[fogIndex] === 1);
458:       obj.userData.selection.visible = entity === frame.selected;
459:       obj.userData.selection.scale.setScalar(entity.size ? 1 : .6);
460:       obj.userData.selection.material.opacity = entity.team === 'blue' ? .9 : .65;
461:       obj.userData.model.rotation.y = 0;
462:       if (turret) turret.rotation.y = aimAngle === null ? 0 : aimAngle - obj.rotation.y;
463:       obj.userData.health.visible = entity.hp < entity.max;
464:       const ratio = Math.max(0, Math.min(1, entity.hp / entity.max));
465:       obj.userData.healthFill.scale.x = ratio;
466:       obj.userData.healthFill.position.x = -(obj.userData.health.userData.width * (1 - ratio)) / 2;
467:       const hopper = obj.getObjectByName('ore hopper');
468:       if (hopper) hopper.material = entity.carry > 0 ? mat('#b6944d') : mat('#756a49');
469:       const vehicle = obj.userData.model.getObjectByName('vehicle');
470:       if (vehicle) vehicle.position.y = entity.kind === 'collector' && entity.harvesting ? Math.sin(frame.time * 2.5) * .08 : 0;
471:     }
472:     for (const [id, obj] of entities) if (!live.has(id)) { entityRoot.remove(obj); disposeTree(obj); entities.delete(id); }
473:     syncResources(frame);
474:     syncEffects(frame);
475:     let ghost = scene.getObjectByName('placement-preview');
476:     if (frame.placement) {
477:       if (!ghost) {
478:         ghost = new THREE.Mesh(new THREE.BoxGeometry(8, 4, 8), new THREE.MeshBasicMaterial({ color: '#c8f05b', wireframe: true, transparent: true, opacity: .8 }));
479:         ghost.name = 'placement-preview'; scene.add(ghost);
480:       }
481:       const pointer = frame.pointer || { x: .5, y: .5 };
482:       position(ghost, pointer.x, pointer.y, 2); ghost.visible = true;
483:     } else if (ghost) ghost.visible = false;
484:     renderer.render(scene, camera);
