517:   function syncEffects(frame) {
518:     const key = `${frame.shots.length}:${frame.particles.length}:${Math.floor(frame.time * 10)}`;
519:     if (transientKey === key) return;
520:     transientKey = key;
521:     while (transientRoot.children.length) {
522:       const child = transientRoot.children[0]; transientRoot.remove(child); disposeTree(child);
523:     }
524:     const up = new THREE.Vector3(0, 1, 0);
525:     const addTracer = (from, to, radius, color) => {
526:       const delta = to.clone().sub(from), length = delta.length();
527:       if (length < .025) return;
528:       const tracer = new THREE.Mesh(new THREE.CylinderGeometry(radius * .72, radius, length, 6), basic(color));
529:       tracer.position.copy(from).add(to).multiplyScalar(.5);
530:       tracer.quaternion.setFromUnitVectors(up, delta.normalize());
531:       transientRoot.add(tracer);
532:     };
533:     for (const shot of frame.shots) {
534:       if (!shot.target) continue;
535:       const t = Math.max(0, Math.min(1, 1 - shot.life / shot.max));
536:       const weapon = shot.weapon || (shot.sourceKind === 'tank' ? 'cannon' : shot.sourceKind === 'infantry' ? 'rifle' : 'machinegun');
537:       const height = weapon === 'missile' ? 5.2 : weapon === 'cannon' ? 2.65 : weapon === 'flak' ? 3.15 : weapon === 'autocannon' ? 2.45 : weapon === 'rifle' ? 1.45 : 2.05;
538:       const a = new THREE.Vector3((shot.x - .5) * WORLD * aspect, height, (shot.y - .5) * WORLD);
539:       const progress = t;
540:       const arc = weapon === 'cannon' ? Math.sin(Math.PI * progress) * 3.8 : weapon === 'flak' ? Math.sin(Math.PI * progress) * 2.2 : 0;
541:       const b = new THREE.Vector3((shot.x + (shot.target.x - shot.x) * progress - .5) * WORLD * aspect, height + arc, (shot.y + (shot.target.y - shot.y) * progress - .5) * WORLD);
542:       const direction = b.clone().sub(a).normalize();
543:       const color = shot.color || '#f4d781';
544:       if (weapon === 'cannon') {
545:         const trailStart = b.clone().lerp(a, .22);
546:         addTracer(trailStart, b, .11, '#ffd77a');
547:         const shell = new THREE.Mesh(new THREE.SphereGeometry(.34, 10, 8), mat('#3c3b32', .38, .62));
548:         shell.position.copy(b); shell.scale.set(.9, .8, 1.25); transientRoot.add(shell);
549:         const glint = new THREE.Mesh(new THREE.SphereGeometry(.16, 8, 6), basic('#ffb34e'));
550:         glint.position.copy(b); transientRoot.add(glint);
551:       } else if (weapon === 'missile') {
552:         const trailStart = b.clone().lerp(a, .16);
553:         addTracer(trailStart, b, .16, '#ef9d4c');
554:         const missile = new THREE.Group();
555:         const body = new THREE.Mesh(new THREE.CylinderGeometry(.14, .2, .95, 8), mat('#55564a', .42, .55));
556:         body.rotation.x = Math.PI / 2; missile.add(body);
557:         const nose = new THREE.Mesh(new THREE.ConeGeometry(.15, .34, 8), mat('#c4b58b', .48, .35));
558:         nose.rotation.x = -Math.PI / 2; nose.position.z = -.62; missile.add(nose);
559:         for (let i = 0; i < 4; i++) {
560:           const fin = new THREE.Mesh(new THREE.BoxGeometry(.34, .07, .27), mat('#383b34', .55, .4));
561:           fin.position.set(Math.cos(i * Math.PI / 2) * .19, Math.sin(i * Math.PI / 2) * .19, .31); missile.add(fin);
562:         }
563:         missile.position.copy(b); missile.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, -1), direction);
564:         transientRoot.add(missile);
565:         const flame = new THREE.Mesh(new THREE.ConeGeometry(.19, .62, 8), basic('#ff7838', .9));
566:         flame.position.copy(b).addScaledVector(direction, -.68);
567:         flame.quaternion.setFromUnitVectors(up, direction.clone().negate()); transientRoot.add(flame);
568:       } else if (weapon === 'flak') {
569:         addTracer(b.clone().lerp(a, .28), b, .095, '#ffb75d');
570:         const shell = new THREE.Mesh(new THREE.SphereGeometry(.23, 9, 7), mat('#51483a', .46, .5));
571:         shell.position.copy(b); transientRoot.add(shell);
572:         const glow = new THREE.Mesh(new THREE.SphereGeometry(.34, 8, 6), basic('#ff9e49', .35));
573:         glow.position.copy(b); transientRoot.add(glow);
574:       } else {
575:         const radius = weapon === 'autocannon' ? .062 : weapon === 'rifle' ? .032 : .048;
576:         const tracerColor = weapon === 'rifle' ? '#f5e4ad' : weapon === 'autocannon' ? '#ffb94e' : color;
577:         addTracer(a, b, radius, tracerColor);
578:         const tip = new THREE.Mesh(new THREE.SphereGeometry(weapon === 'autocannon' ? .13 : .085, 7, 5), basic(tracerColor));
579:         tip.position.copy(b); transientRoot.add(tip);
580:       }
581:     }
582:     for (const particle of frame.particles) {
583:       const mesh = new THREE.Mesh(new THREE.SphereGeometry(.35 + (1 - particle.life / particle.max) * 1.7, 8, 6), basic(particle.color, Math.max(.12, particle.life / particle.max)));
584:       position(mesh, particle.x, particle.y, .8); transientRoot.add(mesh);
585:     }
586:   }
